<?php
declare(strict_types=1);
/** Native PHP database recovery SQL, deliberately distinct from Node staging exports. */
final class DatabaseExport
{
    public const LIMIT=536870912;
    private const EMPTY_DATA=['jingo_sessions','jingo_pos_sessions','jingo_partner_sessions','jingo_admin_otp','jingo_admin_login_limits','jingo_pos_login_limits','jingo_partner_login_limits','jingo_order_limits','jingo_contact_limits'];
    public function __construct(private PDO $db,private int $limit=self::LIMIT){}
    private static function identifier(string $name):string{if(!preg_match('/^[a-z_][a-z0-9_]{0,63}$/D',$name))throw new HttpError(409,'Có tên bảng/cột không được hỗ trợ.');return '`'.$name.'`';}
    public function create(string $actor)
    {
        if($this->db->inTransaction())throw new HttpError(409,'Hoàn tất giao dịch hiện tại trước khi xuất database.');
        $database=$this->db->query('SELECT DATABASE()')->fetchColumn();$lock='jingo-export-'.substr(hash('sha256',$database),0,40);$q=$this->db->prepare('SELECT GET_LOCK(?,0)');$q->execute([$lock]);if((int)$q->fetchColumn()!==1)throw new HttpError(409,'Đang xuất database. Chờ rồi thử lại.');$file=null;$size=0;
        try{$file=tmpfile();if(!$file)throw new HttpError(503,'Không mở được file xuất tạm.');$path=realpath(stream_get_meta_data($file)['uri']);$public=realpath(dirname(__DIR__).'/public');if(!$path||$public&&str_starts_with(strtolower(str_replace('\\','/',$path)),strtolower(str_replace('\\','/',$public)).'/'))throw new HttpError(503,'Thư mục tạm phải ngoài public.');
            $write=function(string $text)use($file,&$size){$size+=strlen($text);if($size>$this->limit)throw new HttpError(413,'Bản xuất vượt giới hạn. Dùng công cụ sao lưu của hosting.');for($i=0,$n=strlen($text);$i<$n;){$bytes=fwrite($file,substr($text,$i));if($bytes===false||$bytes===0)throw new HttpError(503,'Không ghi được file xuất.');$i+=$bytes;}};
            $this->db->exec("SET time_zone='+00:00'");$this->db->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$this->db->exec('START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY');
            $q=$this->db->prepare("SELECT TABLE_NAME,ENGINE,TABLE_TYPE FROM information_schema.TABLES WHERE TABLE_SCHEMA=? ORDER BY TABLE_NAME");$q->execute([$database]);$tables=array_values(array_filter($q->fetchAll(PDO::FETCH_ASSOC),fn($t)=>str_starts_with($t['TABLE_NAME'],'jingo_')));if(!$tables)throw new HttpError(409,'Không có bảng PHP để xuất.');$write('-- JinMemo PHP database v1; '.gmdate('c')."\n-- PRIVATE RECOVERY SQL. Import only into a NEW EMPTY database. Not jm_transfer staging.\n-- Contains private business data, password hashes and encrypted settings. Files and .smtp-key are NOT included.\n-- Login sessions, OTP and rate limits are intentionally empty. No DROP or overwrite.\nSET NAMES utf8mb4;\nSET time_zone='+00:00';\nSET FOREIGN_KEY_CHECKS=0;\n");$counts=[];
            foreach($tables as $table){$name=$table['TABLE_NAME'];$id=self::identifier($name);if($table['TABLE_TYPE']!=='BASE TABLE'||strtoupper($table['ENGINE']??'')!=='INNODB')throw new HttpError(409,'Chỉ xuất snapshot các bảng InnoDB.');$ddl=$this->db->query('SHOW CREATE TABLE '.$id)->fetch(PDO::FETCH_NUM)[1];$write($ddl.";\n");$q=$this->db->prepare('SELECT COLUMN_NAME,DATA_TYPE,EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$database,$name]);$columns=array_values(array_filter($q->fetchAll(PDO::FETCH_ASSOC),fn($c)=>!preg_match('/(?:VIRTUAL|STORED) GENERATED/i',$c['EXTRA'])));$count=0;
                if(!in_array($name,self::EMPTY_DATA,true)&&$columns){$names=implode(',',array_map(fn($c)=>self::identifier($c['COLUMN_NAME']),$columns));$select=implode(',',array_map(fn($c)=>in_array(strtolower($c['DATA_TYPE']),['binary','varbinary','tinyblob','blob','mediumblob','longblob','bit'],true)?'HEX('.self::identifier($c['COLUMN_NAME']).') AS '.self::identifier($c['COLUMN_NAME']):self::identifier($c['COLUMN_NAME']),$columns));$this->db->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);$rows=$this->db->query('SELECT '.$select.' FROM '.$id);try{while($row=$rows->fetch(PDO::FETCH_NUM)){$values=[];foreach($columns as $i=>$c){$value=$row[$i];if($value===null){$values[]='NULL';continue;}$binary=in_array(strtolower($c['DATA_TYPE']),['binary','varbinary','tinyblob','blob','mediumblob','longblob','bit'],true);$hex="X'".($binary?(string)$value:bin2hex((string)$value))."'";$values[]=$binary?$hex:'CONVERT('.$hex.' USING utf8mb4)';}$write('INSERT INTO '.$id.' ('.$names.') VALUES ('.implode(',',$values).");\n");$count++;}}finally{$rows->closeCursor();$this->db->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,true);}}
                $counts[$name]=$count;$write('-- '.$name.': '.$count." rows\n");}
            $write("SET FOREIGN_KEY_CHECKS=1;\n-- PHP DATABASE COMPLETE ".json_encode($counts,JSON_THROW_ON_ERROR)."\n");$this->db->exec('COMMIT');$q=$this->db->prepare('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)');$q->execute([bin2hex(random_bytes(16)),$actor,'backup.database.export','php-database-v1']);rewind($file);$out=$file;$file=null;return $out;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}finally{if(is_resource($file))fclose($file);$this->db->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,true);$q=$this->db->prepare('SELECT RELEASE_LOCK(?)');$q->execute([$lock]);}
    }
}
